import Foundation

/// Broad US pronunciation reference derived from CMUdict, not generated by an LLM.
/// The upstream stress/phoneme choices are retained; readings have no POS ranking.
actor AmericanPronunciation {
    static let shared = AmericanPronunciation()
    private var entries: [String: [[String]]]?

    static var resourceURL: URL? {
        if Bundle.main.bundleURL.pathExtension == "app", let resources = Bundle.main.resourceURL {
            for prefix in ["DictionaryApp_DictionaryApp.bundle/Contents/Resources", "DictionaryApp_DictionaryApp.bundle", ""] {
                let url = resources.appendingPathComponent(prefix).appendingPathComponent("Pronunciation/cmudict.dict")
                if FileManager.default.fileExists(atPath: url.path) { return url }
            }
            return nil
        }
        return Bundle.module.url(forResource: "cmudict", withExtension: "dict", subdirectory: "Pronunciation")
    }

    func lookup(_ raw: String) -> [String] {
        let word = raw.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        guard word.range(of: "^[a-z]+(?:['-][a-z]+)*$", options: .regularExpression) != nil else { return [] }
        if entries == nil {
            guard let url = Self.resourceURL, let text = try? String(contentsOf: url, encoding: .utf8) else { return [] }
            var index: [String: [[String]]] = [:]
            for line in text.split(separator: "\n") {
                let parts = line.split(separator: " ").map(String.init)
                guard parts.count > 1 else { continue }
                let lemma = parts[0].replacingOccurrences(of: "\\([0-9]+\\)$", with: "", options: .regularExpression)
                let phones = Array(parts.dropFirst().prefix(while: { !$0.hasPrefix("#") }))
                index[lemma, default: []].append(phones)
            }
            entries = index
        }
        var seen = Set<String>()
        return (entries?[word] ?? []).compactMap(Self.ipa).filter { seen.insert($0).inserted }
    }

    static func ipa(_ phones: [String]) -> String? {
        let symbols = ["AA":"ɑ", "AE":"æ", "AH":"ʌ", "AO":"ɔ", "AW":"aʊ", "AY":"aɪ", "B":"b", "CH":"tʃ", "D":"d", "DH":"ð", "EH":"ɛ", "ER":"ɝ", "EY":"eɪ", "F":"f", "G":"ɡ", "HH":"h", "IH":"ɪ", "IY":"i", "JH":"dʒ", "K":"k", "L":"l", "M":"m", "N":"n", "NG":"ŋ", "OW":"oʊ", "OY":"ɔɪ", "P":"p", "R":"ɹ", "S":"s", "SH":"ʃ", "T":"t", "TH":"θ", "UH":"ʊ", "UW":"u", "V":"v", "W":"w", "Y":"j", "Z":"z", "ZH":"ʒ"]
        let onsets: Set<String> = ["P R","P L","B R","B L","T R","D R","K R","K L","G R","G L","F R","F L","TH R","SH R","S P","S T","S K","S M","S N","S L","S W","T W","D W","K W","G W","S P R","S P L","S T R","S K R","S K W"]
        var values: [String] = [], stress: [Int: String] = [:], previousVowel: Int?
        for (index, phone) in phones.enumerated() {
            let base = String(phone.prefix(while: { !$0.isNumber }))
            guard var value = symbols[base] else { return nil }
            if phone.last == "0" { if base == "AH" { value = "ə" }; if base == "ER" { value = "ɚ" } }
            if let last = phone.last, last.isNumber {
                if last == "1" || last == "2" {
                    var onset = 0
                    if let previousVowel {
                        onset = index
                        if index > previousVowel + 1 {
                            onset = index - 1
                            for candidate in (previousVowel + 1)..<index {
                                if onsets.contains(phones[candidate..<index].joined(separator: " ")) { onset = candidate; break }
                            }
                        }
                    }
                    stress[onset] = last == "1" ? "ˈ" : "ˌ"
                }
                previousVowel = index
            }
            values.append(value)
        }
        guard !values.isEmpty else { return nil }
        return values.indices.map { (stress[$0] ?? "") + values[$0] }.joined()
    }
}
